  --card-shad-hov: 0 4px 16px rgba(0,0,0,.5);
}

/* ── Reset ──────────────────────────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
[hidden] { display: none !important; }
html { scroll-behavior: smooth; }
body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  transition: background var(--trans), color var(--trans);
}
a { color: var(--accent); text-decoration: none; }
a:hover { text-decoration: underline; }
button { cursor: pointer; font-family: inherit; }

/* ── Layout ─────────────────────────────────────────────────────────────── */
.container { max-width: 860px; margin: 0 auto; padding: 0 20px; }

/* ── Header ─────────────────────────────────────────────────────────────── */
.header {
  position: sticky; top: 0; z-index: 100;
  background: var(--bg);
  border-bottom: 1px solid var(--border);
  backdrop-filter: saturate(180%) blur(6px);
}
.header .container {
  display: flex; align-items: center; justify-content: space-between;
  height: 56px;
}
.brand { display: flex; align-items: center; gap: 10px; }
.brand-icon { font-size: 1.4rem; }
.brand-name { font-size: 1.05rem; font-weight: 600; letter-spacing: -.3px; }

.theme-btn {
  background: none; border: 1px solid var(--border);
  border-radius: 8px; padding: 6px 10px; font-size: 1rem;
  color: var(--text-sec);
  transition: border-color var(--trans), color var(--trans);
}
.theme-btn:hover { color: var(--text); border-color: var(--text-sec); }

/* ── Search section ─────────────────────────────────────────────────────── */
.search-section {
  padding: 72px 0 48px;
  transition: padding var(--trans);
}
.search-section.compact { padding: 28px 0 20px; }

.search-hero { text-align: center; }
.search-subtitle {
  font-size: .95rem; color: var(--text-sec);
  margin-bottom: 24px; letter-spacing: -.1px;

