@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Cairo:wght@400;600&display=swap');

/* ── Variables ──────────────────────────────────────────────────────────── */
:root {
  --bg:          #ffffff;
  --surface:     #f4f6f8;
  --surface2:    #eef0f3;
  --border:      #e2e5ea;
  --text:        #111827;
  --text-sec:    #6b7280;
  --text-ter:    #9ca3af;
  --accent:      #059669;
  --accent-hov:  #047857;
  --accent-dim:  color-mix(in srgb, #059669 12%, transparent);
  --card-shad:   0 1px 3px rgba(0,0,0,.07), 0 1px 2px rgba(0,0,0,.04);
  --card-shad-hov: 0 6px 18px rgba(0,0,0,.09);
  --radius:      12px;
  --radius-sm:   7px;
  --font:        'Inter', system-ui, -apple-system, sans-serif;
  --font-ar:     'Cairo', 'Amiri', 'Noto Naskh Arabic', serif;
  --trans:       .16s ease;
}

[data-theme="dark"] {
  --bg:          #0d1117;
  --surface:     #161b22;
  --surface2:    #1c2128;
  --border:      #30363d;
  --text:        #e6edf3;
  --text-sec:    #8b949e;
  --text-ter:    #6e7681;
  --accent:      #3fb87a;
  --accent-hov:  #56d68f;
  --accent-dim:  color-mix(in srgb, #3fb87a 14%, transparent);
  --card-shad:   0 1px 3px rgba(0,0,0,.4);
  --card-shad-hov: 0 6px 20px rgba(0,0,0,.55);
}

/* ── Reset ──────────────────────────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
[hidden] { display: none !important; }
html { scroll-behavior: smooth; }
body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  transition: background var(--trans), color var(--trans);
  line-height: 1.6;
}
a { color: var(--accent); text-decoration: none; }
a:hover { text-decoration: underline; }
button { cursor: pointer; font-family: inherit; }

/* ── Layout ─────────────────────────────────────────────────────────────── */
.container { max-width: 820px; margin: 0 auto; padding: 0 20px; }

/* ── Header ─────────────────────────────────────────────────────────────── */
.header {
  position: sticky; top: 0; z-index: 100;
  background: var(--bg);
  border-bottom: 1px solid var(--border);
  backdrop-filter: saturate(180%) blur(8px);
  -webkit-backdrop-filter: saturate(180%) blur(8px);
}
.header .container {
  display: flex; align-items: center; justify-content: space-between;
  height: 54px;
}
.brand { display: flex; align-items: center; gap: 9px; }
.brand-icon { font-size: 1.3rem; }
.brand-name { font-size: 1rem; font-weight: 600; letter-spacing: -.2px; }

.theme-btn {
  background: none; border: 1px solid var(--border);
  border-radius: 8px; padding: 5px 10px; font-size: 1rem;
  color: var(--text-sec);
  transition: border-color var(--trans), color var(--trans);
}
.theme-btn:hover { color: var(--text); border-color: var(--text-sec); }

/* ── Search section ─────────────────────────────────────────────────────── */
.search-section { padding: 68px 0 44px; transition: padding var(--trans); }
.search-section.compact { padding: 22px 0 16px; }
.search-section.compact .hero-intro { display: none; }

.search-hero { text-align: center; }

.hero-intro { margin-bottom: 28px; }
.hero-title {
  font-size: 2rem; font-weight: 700;
  letter-spacing: -.5px; color: var(--text);
  margin-bottom: 10px;
}
.hero-subtitle {
  font-size: .93rem; color: var(--text-sec);
  max-width: 560px; margin: 0 auto; line-height: 1.65;
}

/* Search box */
.search-box-wrapper { max-width: 660px; margin: 0 auto; }
.search-box {
  display: flex; align-items: center; gap: 8px;
  background: var(--bg);
  border: 2px solid var(--border);
  border-radius: 50px;
  padding: 8px 8px 8px 18px;
  box-shadow: var(--card-shad);
  transition: border-color .14s, box-shadow .14s;
}
.search-box:focus-within {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-dim);
}
.search-icon {
  flex-shrink: 0; color: var(--text-sec);
  display: flex; align-items: center;
}
#search-input {
  flex: 1; border: none; outline: none;
  background: transparent; color: var(--text);
  font-size: .95rem; font-family: inherit;
}
#search-input::placeholder { color: var(--text-ter); }
.search-btn {
  background: var(--accent); color: white;
  border: none; border-radius: 40px;
  padding: 8px 22px; font-size: .88rem; font-weight: 500;
  flex-shrink: 0;
  transition: background var(--trans);
}
.search-btn:hover { background: var(--accent-hov); }

/* ── Search progress bar ────────────────────────────────────────────────── */
.search-progress {
  display: flex; align-items: center; justify-content: center;
  gap: 6px; margin-top: 18px; flex-wrap: wrap;
}
.progress-step {
  display: flex; align-items: center; gap: 7px;
  font-size: .8rem; color: var(--text-ter);
  padding: 5px 13px;
  border-radius: 20px;
  border: 1px solid var(--border);
  background: var(--surface);
  transition: color var(--trans), border-color var(--trans), background var(--trans);
}
.progress-step .step-dot {
  width: 7px; height: 7px; border-radius: 50%;
  background: var(--border);
  transition: background var(--trans);
  flex-shrink: 0;
}
.progress-step.active {
  color: var(--accent); border-color: var(--accent);
  background: var(--accent-dim);
}
.progress-step.active .step-dot {
  background: var(--accent);
  box-shadow: 0 0 0 2px var(--accent-dim);
  animation: pulse .9s ease infinite;
}
.progress-step.done {
  color: var(--text-sec); border-color: var(--border);
}
.progress-step.done .step-dot { background: var(--accent); }
.progress-arrow { color: var(--text-ter); font-size: .85rem; }

@keyframes pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50%       { opacity: .55; transform: scale(1.3); }
}

/* ── Filter bar ─────────────────────────────────────────────────────────── */
.filter-bar {
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  padding: 10px 0;
  position: sticky; top: 54px; z-index: 90;
}
.filter-row {
  display: flex; align-items: center; gap: 10px; flex-wrap: wrap;
}
.filter-controls { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.filter-select {
  background: var(--bg); color: var(--text);
  border: 1px solid var(--border); border-radius: var(--radius-sm);
  padding: 5px 10px; font-size: .83rem; font-family: inherit;
  cursor: pointer;
  transition: border-color var(--trans);
}
.filter-select:focus { outline: none; border-color: var(--accent); }
.clear-btn {
  background: none; border: 1px solid var(--border);
  border-radius: var(--radius-sm); padding: 5px 12px;
  font-size: .82rem; color: var(--text-sec);
  transition: border-color var(--trans), color var(--trans);
}
.clear-btn:hover { border-color: var(--text-sec); color: var(--text); }
.results-count {
  margin-left: auto; font-size: .82rem; color: var(--text-sec);
  white-space: nowrap;
}

/* Pipeline info strip */
.pipeline-info {
  display: flex; align-items: center; flex-wrap: wrap;
  gap: 8px; margin-top: 8px;
  padding: 7px 12px;
  background: var(--accent-dim);
  border: 1px solid color-mix(in srgb, var(--accent) 25%, transparent);
  border-radius: var(--radius-sm);
  font-size: .8rem;
}
.pi-label { color: var(--text-sec); font-weight: 500; flex-shrink: 0; }
.pi-arabic {
  font-family: var(--font-ar); font-size: .95rem;
  color: var(--text); font-weight: 600;
}
.pi-roots { display: flex; flex-wrap: wrap; gap: 4px; }
.root-chip {
  font-family: var(--font-ar); font-size: .8rem;
  background: var(--bg); color: var(--accent);
  border: 1px solid color-mix(in srgb, var(--accent) 30%, transparent);
  border-radius: 4px; padding: 1px 7px;
}

/* ── Loading state ──────────────────────────────────────────────────────── */
.loading-state {
  display: flex; flex-direction: column; align-items: center;
  justify-content: center; padding: 80px 20px; gap: 14px;
  color: var(--text-sec); font-size: .93rem;
}
.loading-spinner {
  width: 34px; height: 34px;
  border: 3px solid var(--border);
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: spin .7s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

/* ── Results section ────────────────────────────────────────────────────── */
.results-section { padding: 24px 0 64px; }
.results-grid { display: flex; flex-direction: column; gap: 14px; }

/* ── Result card ────────────────────────────────────────────────────────── */
.result-card {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px 22px;
  box-shadow: var(--card-shad);
  transition: box-shadow var(--trans), border-color var(--trans);
}
.result-card:hover {
  box-shadow: var(--card-shad-hov);
  border-color: color-mix(in srgb, var(--accent) 35%, var(--border));
}

/* Card meta row */
.card-meta {
  display: flex; align-items: center; flex-wrap: wrap;
  gap: 6px; margin-bottom: 14px;
}
.ref-badge {
  background: var(--accent); color: white;
  border-radius: var(--radius-sm); padding: 3px 11px;
  font-size: .78rem; font-weight: 600; letter-spacing: .1px;
}
.badge {
  font-size: .73rem; border-radius: 5px;
  padding: 2px 8px; font-weight: 500; letter-spacing: .1px;
}
.badge-mecca  { background: #fef3c7; color: #92400e; }
.badge-medina { background: #d1fae5; color: #065f46; }
[data-theme="dark"] .badge-mecca  { background: #451a03; color: #fcd34d; }
[data-theme="dark"] .badge-medina { background: #022c22; color: #6ee7b7; }
.badge-juz { background: var(--surface2); color: var(--text-sec); }

/* Arabic text */
.ayah-arabic {
  font-family: var(--font-ar);
  font-size: 1.38rem;
  line-height: 2.15;
  color: var(--text);
  text-align: right;
  border-bottom: 1px solid var(--border);
  padding-bottom: 14px;
  margin-bottom: 14px;
}

/* Translation */
.ayah-translation { font-size: .9rem; line-height: 1.72; color: var(--text-sec); }
.primary-trans { margin: 0; }

.other-trans {
  margin-top: 12px;
  display: flex; flex-direction: column; gap: 10px;
  padding-top: 10px;
  border-top: 1px dashed var(--border);
}
.other-trans-item { display: flex; flex-direction: column; gap: 3px; }
.trans-label {
  font-size: .72rem; font-weight: 600;
  color: var(--text-ter); text-transform: uppercase; letter-spacing: .5px;
}

.toggle-trans {
  background: none; border: none; padding: 0;
  font-size: .8rem; color: var(--accent); margin-top: 7px;
  text-align: left;
  transition: opacity var(--trans);
}
.toggle-trans:hover { opacity: .75; }

/* Keyword highlight */
mark {
  background: color-mix(in srgb, #f59e0b 22%, transparent);
  color: inherit; border-radius: 2px; padding: 0 1px;
}
[data-theme="dark"] mark {
  background: color-mix(in srgb, #f59e0b 18%, transparent);
}

/* Match info row */
.match-info {
  display: flex; align-items: center; flex-wrap: wrap;
  gap: 5px; margin-top: 12px; padding-top: 11px;
  border-top: 1px solid var(--border);
}
.match-via { font-size: .73rem; color: var(--text-ter); margin-right: 2px; flex-shrink: 0; }
.match-chip {
  font-size: .73rem; font-weight: 500;
  border-radius: 4px; padding: 2px 7px;
}
.match-root {
  font-family: var(--font-ar); font-size: .8rem;
  background: var(--accent-dim);
  color: var(--accent);
  border: 1px solid color-mix(in srgb, var(--accent) 25%, transparent);
}
.match-kw {
  background: color-mix(in srgb, #f59e0b 14%, var(--surface));
  color: #92400e;
}
[data-theme="dark"] .match-kw { color: #fcd34d; }
.match-pattern {
  background: color-mix(in srgb, #6366f1 12%, var(--surface));
  color: #4338ca; font-size: .7rem;
}
[data-theme="dark"] .match-pattern { color: #a5b4fc; }

/* ── Load more ──────────────────────────────────────────────────────────── */
.load-more-wrapper { text-align: center; margin-top: 28px; }
.load-more-btn {
  background: var(--surface); border: 1px solid var(--border);
  border-radius: 40px; padding: 10px 36px;
  font-size: .88rem; color: var(--text);
  transition: background var(--trans), border-color var(--trans);
}
.load-more-btn:hover {
  background: var(--accent-dim); border-color: var(--accent);
}

/* ── No results ─────────────────────────────────────────────────────────── */
.no-results { text-align: center; padding: 64px 20px; }
.no-results-title { font-size: 1rem; color: var(--text); margin-bottom: 8px; }
.no-results-hint { font-size: .85rem; color: var(--text-sec); max-width: 440px; margin: 0 auto; line-height: 1.6; }

/* ── Footer ─────────────────────────────────────────────────────────────── */
.footer {
  border-top: 1px solid var(--border);
  padding: 24px 0;
  text-align: center;
  font-size: .78rem; color: var(--text-ter);
  display: flex; flex-direction: column; gap: 6px;
}

/* ── Responsive ─────────────────────────────────────────────────────────── */
@media (max-width: 600px) {
  .search-section { padding: 44px 0 28px; }
  .hero-title { font-size: 1.5rem; }
  .ayah-arabic { font-size: 1.18rem; }
  .filter-controls { gap: 6px; }
  .filter-select { font-size: .79rem; padding: 4px 7px; }
  .search-progress { gap: 4px; }
