  // ── Section 1: Vocative patterns (يَا ... forms) ─────────────────────
  const addrWithCounts = this.engine.countForAddressees();
  const matchedIds     = new Set(parsed.addresseeIds);
  // Show all addressees, matched ones first
  addrWithCounts.sort((a, b) => {
